// VENDORED ASSET — DO NOT EDIT BY HAND.
// Byte-identical copy of the shared VGI landing page authored in
// vgi-web-frontend/public/landing.html and served by every VGI worker
// (see vgi/docs/http-landing-contract.md). The page is base64-embedded so
// it survives single-file bundling (bun build) unchanged and is served as
// raw bytes. Regenerate with scripts/vendor-landing-html.mjs.

const LANDING_HTML_B64 =
  "";

function decodeBase64(b64: string): Uint8Array {
  // atob is available on Node >=16, Bun, Deno, and workerd.
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** The vendored shared landing page, decoded to its raw UTF-8 bytes. */
export const LANDING_HTML_BYTES: Uint8Array = decodeBase64(LANDING_HTML_B64);
